public void onEnable() {
        plugin = this;
        config = new PlaytimeConfig(this);
        config.load();

        // Initialize the playtime manager
        playtimeManager = new PlaytimeManager(this);

        // Register events
        getServer().getPluginManager().registerEvents(new PlaytimeListener(this), this);

        // Register commands
        getCommand("playtime").setExecutor(new PlaytimeCommand(this));
        getCommand("playtime").setTabCompleter(new PlaytimeTabCompleter(this));

        // Schedule periodic tasks
        scheduler = getServer().getScheduler().runTaskTimerAsynchronously(this, () -> {
            playtimeManager.updateAllPlayers();
        }, 0L, 20L * 60L); // Update every minute

        // Load player data on enable
        playtimeManager.loadAllPlayers();

        getLogger().info("Playtime module enabled!");
    }

