    public void send(final Message msg) {

        if (msg instanceof DelayedMessage) {

            new Delay((DelayedMessage) msg) {

                @Override
                public void delayedAction() {

                    synchronized (sendQueue) {
                        sendQueue.offer(msg);
                        sendQueue.notify();
                    }
                }

            }.start();

        } else {

            synchronized (sendQueue) {
                sendQueue.offer(msg);
                sendQueue.notify();
            }
        }
    }

